:root {
  color-scheme: dark;
  --ink: #17231f;
  --panel: #24332d;
  --panel-light: #304239;
  --mint: #b6ef9f;
  --cream: #f5f0dc;
  --muted: #b5c5b2;
  --orange: #ffbd69;
  --red: #ff8b7c;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  place-items: center;
  background-color: var(--ink);
  background-image: radial-gradient(#304239 1.5px, transparent 1.5px);
  background-size: 24px 24px;
  color: var(--cream);
  font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}

.board {
  width: min(100%, 520px);
  overflow: hidden;
  border: 2px solid #506453;
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 8px 8px 0 #111a16;
}

.topbar {
  min-height: 62px;
  padding: 12px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid #43564a;
}

.pixel-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 2px solid var(--ink);
  border-radius: 4px;
  background: var(--mint);
  color: var(--ink);
  font-weight: 900;
  box-shadow: 3px 3px 0 var(--ink);
}

.game-label, .round, .eyebrow, footer, .score-caption {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .1em;
}
.game-label { color: var(--mint); }
.round { margin-left: auto; color: var(--muted); letter-spacing: .06em; }
.game-content { padding: 32px 36px 30px; }
.eyebrow { margin: 0 0 7px; color: var(--orange); }
h1 { margin: 0; font-size: clamp(30px, 8vw, 38px); line-height: 1.15; letter-spacing: -.04em; }
.prompt { margin: 12px 0 24px; color: var(--muted); }

.letter-tray {
  min-height: 90px;
  padding: 16px 12px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: clamp(5px, 2vw, 10px);
  border: 1px dashed #6b806e;
  border-radius: 8px;
  background: var(--ink);
  color: var(--mint);
  font-size: clamp(24px, 7vw, 34px);
  font-weight: 850;
  letter-spacing: .06em;
}

.tile {
  width: clamp(34px, 9vw, 44px);
  height: clamp(42px, 11vw, 50px);
  display: grid;
  place-items: center;
  border: 1px solid #69816d;
  border-bottom-width: 4px;
  border-radius: 5px;
  background: var(--panel-light);
}

.hint { margin: 18px 0 8px; color: var(--muted); font-size: 14px; }
label { display: block; margin-bottom: 7px; font-weight: 700; }
input {
  width: 100%;
  min-height: 52px;
  padding: 10px 14px;
  border: 2px solid #6c806e;
  border-radius: 7px;
  outline: none;
  background: #1b2923;
  color: var(--cream);
  font: inherit;
  font-size: 18px;
}
input:focus { border-color: var(--mint); box-shadow: 0 0 0 3px #b6ef9f33; }
.feedback { min-height: 26px; margin: 9px 0 16px; color: var(--muted); font-weight: 650; }
.feedback[data-state="correct"] { color: var(--mint); }
.feedback[data-state="wrong"] { color: var(--red); }
.actions { display: flex; gap: 12px; }
.button {
  min-height: 48px;
  padding: 10px 16px;
  border: 2px solid transparent;
  border-radius: 7px;
  cursor: pointer;
  font: inherit;
  font-weight: 800;
  transition: transform .12s ease, filter .12s ease, box-shadow .12s ease;
}
.button:hover:not(:disabled) { filter: brightness(1.08); transform: translateY(-2px); }
.button:active:not(:disabled) { transform: translateY(1px); box-shadow: none; }
.button:focus-visible { outline: 3px solid var(--cream); outline-offset: 3px; }
.button-primary { flex: 1; background: var(--mint); color: var(--ink); box-shadow: 0 4px 0 #77b66e; }
.button-secondary { background: var(--panel-light); border-color: #617566; color: var(--cream); }
.button:disabled { cursor: not-allowed; opacity: .48; }

.results { text-align: center; }
.results .prompt { margin-bottom: 24px; }
.score-card { margin: 12px auto 24px; padding: 20px; display: grid; gap: 2px; border: 1px solid #536b58; border-radius: 8px; background: var(--ink); }
.score-number { color: var(--mint); font-size: 38px; font-weight: 900; }
.score-caption { color: var(--muted); }
.results .button { width: 100%; }
footer { padding: 15px 20px; display: flex; justify-content: center; align-items: center; gap: 8px; border-top: 1px solid #43564a; color: var(--muted); font-size: 11px; letter-spacing: .08em; }
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--mint); }

@media (max-width: 420px) {
  body { padding: 14px; }
  .topbar { padding-inline: 14px; }
  .game-content { padding: 26px 20px 24px; }
  .actions { flex-direction: column; }
  .button { width: 100%; }
}

"use strict";

const words = ["pixel", "planet", "rocket", "garden", "puzzle", "wizard"];
const scrambleSets = ["LIXEP", "TANLEP", "KROECT", "DENGAR", "ZELPZU", "ZARDIW"];
let index = 0;
let score = 0;
let answered = false;

const game = document.querySelector("#game");
const results = document.querySelector("#results");
const round = document.querySelector("#round");
const scramble = document.querySelector("#scramble");
const form = document.querySelector("#answer-form");
const answer = document.querySelector("#answer");
const feedback = document.querySelector("#feedback");
const next = document.querySelector("#next");

function showWord() {
  round.textContent = `WORD ${index + 1} / ${words.length}`;
  scramble.replaceChildren(...scrambleSets[index].split("").map((letter) => {
    const tile = document.createElement("span");
    tile.className = "tile";
    tile.textContent = letter;
    tile.setAttribute("aria-hidden", "true");
    return tile;
  }));
  scramble.setAttribute("aria-label", `Scrambled letters: ${scrambleSets[index].split("").join(" ")}`);
  answer.value = "";
  answer.disabled = false;
  feedback.textContent = "Ready when you are.";
  feedback.dataset.state = "";
  answered = false;
  next.disabled = true;
  document.querySelector("#check").disabled = false;
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  if (answered) return;
  answered = true;
  const correct = answer.value.trim().toLowerCase() === words[index];
  if (correct) {
    score += 1;
    feedback.textContent = "Correct! Nicely spelled.";
    feedback.dataset.state = "correct";
  } else {
    feedback.textContent = `Not quite. The word was “${words[index]}”.`;
    feedback.dataset.state = "wrong";
  }
  answer.disabled = true;
  document.querySelector("#check").disabled = true;
  next.disabled = false;
  next.focus();
});

next.addEventListener("click", () => {
  if (!answered) return;
  index += 1;
  if (index === words.length) {
    game.hidden = true;
    results.hidden = false;
    document.querySelector("#score").textContent = `${score} / ${words.length}`;
    results.focus();
    return;
  }
  showWord();
  answer.focus();
});

document.querySelector("#restart").addEventListener("click", () => {
  index = 0;
  score = 0;
  results.hidden = true;
  game.hidden = false;
  showWord();
  answer.focus();
});

showWord();
